"""Wave-table synthesis helpers for the keygen tune. 44100 Hz mono 16-bit."""
import numpy as np, base64, os

SR = 44100

def to_pcm16(x):
    x = np.asarray(x, dtype=np.float64)
    x = np.clip(x, -1.0, 1.0)
    return (x * 32767.0).astype('<i2')

def b64_int16(x):
    return base64.b64encode(to_pcm16(x).tobytes()).decode()

def b64_float32(x):
    x = np.asarray(x, dtype=np.float32)
    return base64.b64encode(x.tobytes()).decode()

def harm_spec(spec):
    """spec: list of (harmonic, amp, phase). Returns 1-cycle wave, peak-normalised."""
    n = len(spec)
    L = 4096
    t = np.arange(L) / L
    y = np.zeros(L)
    for h, a, p in spec:
        y += a * np.sin(2*np.pi*h*t + p)
    m = np.abs(y).max()
    return y / m if m > 1e-9 else y

def saw_spec(nh, roll=1.0, tilt=0.0):
    """classic saw: 1/k amplitude, plus harmonic tilt (extra roll per harmonic)."""
    return [(k, (1.0/k**roll), 0.0) for k in range(1, nh+1)]

def pulse_wave(nh, duty=0.5):
    L = 4096
    t = np.arange(L)/L
    y = np.where(t < duty, 1.0, -1.0)
    Y = np.fft.rfft(y)
    keep = np.zeros_like(Y)
    keep[:nh+1] = Y[:nh+1]
    y2 = np.fft.irfft(keep, L)
    m = np.abs(y2).max()
    return y2/m

def square_wave(nh):
    return pulse_wave(nh, 0.5)

def soft_clip(y, drive=1.0, k=2.0):
    return np.tanh(drive*y) / np.tanh(drive) if drive > 0 else y

def env_perc(n, a=0.002, d=0.0, s=0.0, curve=3.0):
    """percussive envelope: fast attack, exponential-ish decay to 0."""
    e = np.zeros(n)
    na = max(1, int(a*SR))
    na = min(na, n)
    e[:na] = np.linspace(0, 1, na)
    if n > na:
        t = np.arange(n-na)/(n-na)
        if s > 0:
            e[na:] = 1.0 + (s-1.0)*t
        else:
            e[na:] = np.exp(-curve*t)
    return e

def noise(n):
    rng = np.random.default_rng(1234)
    return rng.uniform(-1, 1, n)
